//! B27T: whole-stream SHA-256 footer. B27S legacy reader retained.
use std::io::{Read,Write};
use sha2::{Sha256,Digest};
pub const BLOCK:usize=256*1024;
const MAX_FRAME:usize=BLOCK*15+4096;
pub fn encode(mut r:impl Read,mut w:impl Write,mode:u8)->std::io::Result<()> {w.write_all(b"B27T")?;let mut hash=Sha256::new();let mut total=0u64;let mut count=0u64;let mut b=vec![0;BLOCK];loop{let mut n=0;while n<BLOCK{let k=r.read(&mut b[n..])?;if k==0{break}n+=k}if n==0{break}hash.update(&b[..n]);total=total.checked_add(n as u64).ok_or_else(||std::io::Error::other("overflow"))?;count+=1;let frame=crate::compress(&b[..n],mode).map_err(std::io::Error::other)?;w.write_all(&(frame.len()as u32).to_be_bytes())?;w.write_all(&frame)?;}w.write_all(&[0;4])?;w.write_all(&total.to_be_bytes())?;w.write_all(&count.to_be_bytes())?;w.write_all(&hash.finalize())}
pub fn decode(r:impl Read,w:impl Write,max:u64)->std::io::Result<()> {decode_policy(r,w,max,false)}
pub fn decode_strict(r:impl Read,w:impl Write,max:u64)->std::io::Result<()> {decode_policy(r,w,max,true)}
fn decode_policy(mut r:impl Read,mut w:impl Write,max:u64,strict:bool)->std::io::Result<()> {let mut h=[0;4];r.read_exact(&mut h)?;let secure=&h==b"B27T";if !secure&&(strict||&h!=b"B27S"){return Err(std::io::Error::other("magic"))}let(mut total,mut count)=(0u64,0u64);let mut hash=Sha256::new();loop{r.read_exact(&mut h)?;let n=u32::from_be_bytes(h)as usize;if n==0{if secure{let mut footer=[0;48];r.read_exact(&mut footer)?;if footer[..8]!=total.to_be_bytes()||footer[8..16]!=count.to_be_bytes()||footer[16..]!=hash.finalize()[..]{return Err(std::io::Error::other("stream integrity"))}}let mut x=[0];if r.read(&mut x)?!=0{return Err(std::io::Error::other("trailing data"))}return Ok(())}if !(41..=MAX_FRAME).contains(&n){return Err(std::io::Error::other("frame limit"))}let mut b=vec![0;n];r.read_exact(&mut b)?;if &b[..4]!=b"B27N"||u32::from_be_bytes(b[5..9].try_into().unwrap())as usize>BLOCK{return Err(std::io::Error::other("block limit"))}let declared=u32::from_be_bytes(b[5..9].try_into().unwrap())as u64;if declared>max.saturating_sub(total){return Err(std::io::Error::other("output limit"))}let p=crate::decompress(&b).map_err(std::io::Error::other)?;if p.is_empty(){return Err(std::io::Error::other("empty frame"))}total=total.checked_add(p.len()as u64).ok_or_else(||std::io::Error::other("overflow"))?;count+=1;if total>max{return Err(std::io::Error::other("output limit"))}hash.update(&p);w.write_all(&p)?}}
